import React, { useEffect, useRef, useState } from 'react';

export default function OpeningSection() {
  const [visible, setVisible] = useState(false);
  const ref = useRef();

  useEffect(() => {
    const obs = new IntersectionObserver(([e]) => {
      if (e.isIntersecting) setVisible(true);
    }, { threshold: 0.2 });
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, []);

  return (
    <section ref={ref} style={{
      background: 'linear-gradient(180deg, #fdf0f8 0%, #fce8f5 100%)',
      padding: '80px 20px 60px',
      textAlign: 'center',
      minHeight: '100vh',
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
    }}>
      <style>{`
        @keyframes fadeUp {
          from { opacity: 0; transform: translateY(30px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .opening-anim { opacity: 0; }
        .opening-anim.visible { animation: fadeUp 0.8s ease forwards; }
        .d1 { animation-delay: 0.1s; }
        .d2 { animation-delay: 0.3s; }
        .d3 { animation-delay: 0.5s; }
        .d4 { animation-delay: 0.7s; }
        .couple-photo-wrap { 
          animation: float 3s ease-in-out infinite;
        }
        @keyframes float {
          0%, 100% { transform: translateY(0); }
          50% { transform: translateY(-10px); }
        }
      `}</style>

      {/* Assalamualaikum */}
      <h2
        className={`opening-anim d1${visible ? ' visible' : ''}`}
        style={{
          fontFamily: "'Dancing Script', cursive",
          fontSize: 'clamp(2rem, 6vw, 3rem)',
          color: '#e91e8c',
          marginBottom: '24px',
        }}
      >
        Assalamu'alaikum
      </h2>

      {/* Bismillah */}
      <p
        className={`opening-anim d2${visible ? ' visible' : ''}`}
        style={{
          fontFamily: "'Amiri', serif",
          fontSize: 'clamp(1.5rem, 4vw, 2.2rem)',
          color: '#333',
          marginBottom: '32px',
          direction: 'rtl',
          lineHeight: 1.8,
        }}
      >
        بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ
      </p>

      {/* Quran verse */}
      <p
        className={`opening-anim d3${visible ? ' visible' : ''}`}
        style={{
          fontFamily: "'Poppins', sans-serif",
          fontSize: 'clamp(0.85rem, 2.5vw, 1rem)',
          color: '#555',
          maxWidth: '700px',
          lineHeight: 1.9,
          marginBottom: '12px',
        }}
      >
        Wahai manusia! Bertakwalah kepada Tuhanmu yang telah menciptakan kamu dari diri yang
        satu (Adam), dan (Allah) menciptakan pasangannya (Hawa) dari (diri)-nya; dan dari keduanya
        Allah memperkembangbiakkan laki-laki dan perempuan yang banyak. Bertakwalah kepada
        Allah yang dengan nama-Nya kamu saling meminta, dan (peliharalah) hubungan
        kekeluargaan. Sesungguhnya Allah selalu menjaga dan mengawasimu.
      </p>

      <p
        className={`opening-anim d3${visible ? ' visible' : ''}`}
        style={{
          fontFamily: "'Poppins', sans-serif",
          fontSize: '0.9rem',
          color: '#888',
          marginBottom: '50px',
          fontStyle: 'italic',
        }}
      >
        (QS. An-Nisa' (4) : 1)
      </p>

      {/* Couple photo */}
      <div
        className={`opening-anim d4${visible ? ' visible' : ''}`}
        style={{ width: '100%', display: 'flex', justifyContent: 'center' }}
      >
        <div className="couple-photo-wrap" style={{
          width: '340px',
          height: '260px',
          borderRadius: '50%',
          overflow: 'hidden',
          background: 'linear-gradient(135deg, #ffd6e8, #f8c0d8)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          boxShadow: '0 10px 40px rgba(233,30,140,0.2)',
          border: '4px solid #f8d0e8',
        }}>
          {/* Illustration placeholder matching Nobita & Shizuka anime style */}
          <CoupleSVG />
        </div>
      </div>
    </section>
  );
}

function CoupleSVG() {
  return (
    <svg viewBox="0 0 340 260" width="340" height="260">
      {/* Background */}
      <defs>
        <radialGradient id="bgGrad" cx="50%" cy="40%" r="60%">
          <stop offset="0%" stopColor="#fffde8" />
          <stop offset="100%" stopColor="#ffd6e8" />
        </radialGradient>
        <radialGradient id="bgGrad2" cx="50%" cy="50%" r="50%">
          <stop offset="0%" stopColor="#e8f8e0" />
          <stop offset="100%" stopColor="#d8f0d0" />
        </radialGradient>
      </defs>
      <rect width="340" height="260" fill="url(#bgGrad)" />

      {/* Background foliage */}
      <ellipse cx="60" cy="60" rx="80" ry="60" fill="#b8e0a0" opacity="0.6" />
      <ellipse cx="280" cy="60" rx="80" ry="60" fill="#b8e0a0" opacity="0.6" />
      <ellipse cx="170" cy="30" rx="100" ry="50" fill="#c8f0a0" opacity="0.5" />

      {/* Roses */}
      {[20, 310].map((x, i) => (
        <g key={i}>
          <circle cx={x} cy="190" r="14" fill="#ff6b9d" opacity="0.8" />
          <circle cx={x} cy="190" r="8" fill="#ff4080" opacity="0.9" />
          <circle cx={x - 8} cy="185" r="6" fill="#ff8ab8" opacity="0.7" />
          <circle cx={x + 8} cy="185" r="6" fill="#ff8ab8" opacity="0.7" />
        </g>
      ))}

      {/* ---- GROOM (Nobita-style) ---- */}
      {/* Body - dark suit */}
      <rect x="88" y="165" width="74" height="90" rx="12" fill="#2d3a5c" />
      {/* Shirt collar */}
      <polygon points="125,165 140,185 110,185" fill="white" />
      {/* Tie */}
      <polygon points="125,170 130,195 120,195" fill="#e91e8c" />
      {/* Head */}
      <ellipse cx="125" cy="120" rx="38" ry="42" fill="#ffd5a8" />
      {/* Hair */}
      <ellipse cx="125" cy="85" rx="36" ry="22" fill="#2d2016" />
      <ellipse cx="95" cy="100" rx="14" ry="18" fill="#2d2016" />
      <ellipse cx="155" cy="100" rx="14" ry="18" fill="#2d2016" />
      {/* Big round glasses */}
      <circle cx="112" cy="122" r="14" fill="none" stroke="#555" strokeWidth="3" />
      <circle cx="138" cy="122" r="14" fill="none" stroke="#555" strokeWidth="3" />
      <line x1="126" y1="122" x2="124" y2="122" stroke="#555" strokeWidth="2" />
      {/* Eyes inside glasses */}
      <circle cx="112" cy="122" r="8" fill="white" />
      <circle cx="138" cy="122" r="8" fill="white" />
      <circle cx="113" cy="123" r="5" fill="#3d2a1a" />
      <circle cx="139" cy="123" r="5" fill="#3d2a1a" />
      <circle cx="115" cy="121" r="2" fill="white" />
      <circle cx="141" cy="121" r="2" fill="white" />
      {/* Nose */}
      <ellipse cx="125" cy="133" rx="4" ry="3" fill="#e8b888" />
      {/* Smile */}
      <path d="M115,142 Q125,150 135,142" fill="none" stroke="#c8806a" strokeWidth="2" strokeLinecap="round" />
      {/* Ear */}
      <ellipse cx="88" cy="122" rx="7" ry="10" fill="#ffd5a8" />
      <ellipse cx="162" cy="122" rx="7" ry="10" fill="#ffd5a8" />
      {/* Flower on lapel */}
      <circle cx="105" cy="175" r="6" fill="#ffb8d0" />
      <circle cx="105" cy="175" r="3" fill="#ff8ab0" />

      {/* ---- BRIDE (Shizuka-style) ---- */}
      {/* Body - white wedding dress */}
      <path d="M178,165 Q195,155 215,155 Q235,155 252,165 L262,255 L168,255 Z" fill="white" />
      {/* Dress details */}
      <path d="M185,180 Q215,170 245,180" fill="none" stroke="#f0d0e8" strokeWidth="2" />
      <path d="M182,195 Q215,185 248,195" fill="none" stroke="#f0d0e8" strokeWidth="2" />
      {/* Head */}
      <ellipse cx="215" cy="115" rx="36" ry="40" fill="#ffd5a8" />
      {/* Hair - black, elegant */}
      <ellipse cx="215" cy="82" rx="34" ry="20" fill="#1a1008" />
      <ellipse cx="183" cy="100" rx="13" ry="22" fill="#1a1008" />
      <ellipse cx="247" cy="100" rx="13" ry="22" fill="#1a1008" />
      {/* Tiara */}
      <path d="M193,80 L198,70 L205,78 L215,65 L225,78 L232,70 L237,80" fill="none" stroke="#ffd700" strokeWidth="3" />
      {/* Eyes */}
      <ellipse cx="204" cy="117" rx="9" ry="10" fill="white" />
      <ellipse cx="226" cy="117" rx="9" ry="10" fill="white" />
      <circle cx="205" cy="118" r="6" fill="#1a0e0a" />
      <circle cx="227" cy="118" r="6" fill="#1a0e0a" />
      <circle cx="207" cy="116" r="2" fill="white" />
      <circle cx="229" cy="116" r="2" fill="white" />
      {/* Eyelashes */}
      <path d="M196,110 Q200,106 208,109" fill="none" stroke="#1a0e0a" strokeWidth="1.5" />
      <path d="M218,109 Q224,106 232,110" fill="none" stroke="#1a0e0a" strokeWidth="1.5" />
      {/* Blush */}
      <ellipse cx="195" cy="128" rx="10" ry="5" fill="#ffb8c8" opacity="0.5" />
      <ellipse cx="235" cy="128" rx="10" ry="5" fill="#ffb8c8" opacity="0.5" />
      {/* Nose */}
      <ellipse cx="215" cy="128" rx="3" ry="2" fill="#e8b888" />
      {/* Smile */}
      <path d="M206,138 Q215,146 224,138" fill="none" stroke="#c8806a" strokeWidth="2" strokeLinecap="round" />
      {/* Ear */}
      <ellipse cx="180" cy="116" rx="7" ry="10" fill="#ffd5a8" />
      <ellipse cx="250" cy="116" rx="7" ry="10" fill="#ffd5a8" />
      {/* Earrings */}
      <circle cx="180" cy="127" r="4" fill="#ffd700" />
      <circle cx="250" cy="127" r="4" fill="#ffd700" />
      {/* Necklace */}
      <path d="M200,158 Q215,165 230,158" fill="none" stroke="#ffd700" strokeWidth="2" />

      {/* Heart between them */}
      <path d="M157,130 C157,126 162,122 165,126 C168,122 173,126 173,130 C173,136 165,142 165,142 C165,142 157,136 157,130Z"
        fill="#e91e8c" opacity="0.8" />

      {/* Ground / grass */}
      <ellipse cx="170" cy="258" rx="140" ry="20" fill="#a8e090" opacity="0.4" />
    </svg>
  );
}
